param([Parameter(Mandatory=$true)][string]$Archive);$ErrorActionPreference='Stop';Set-Location $PSScriptRoot;if(-not(Test-Path $Archive)){throw 'Backup not found'};$ok=Read-Host 'This replaces data. Type RESTORE';if($ok -ne 'RESTORE'){exit 1};docker compose stop atlas;$tmp=Join-Path $env:TEMP ('atlas-restore-'+[guid]::NewGuid());New-Item -ItemType Directory $tmp|Out-Null;try{Expand-Archive $Archive $tmp;$db=Get-ChildItem $tmp -Recurse -Filter atlas.sqlite|Select-Object -First 1;if(-not$db){throw 'Missing database in backup'};docker cp $db.FullName atlas-forex-replay:/data/atlas.sqlite;if($LASTEXITCODE -ne 0){throw 'Could not restore database'};docker compose up -d atlas;Write-Host 'Restore complete'}finally{Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}
